version = version + 1, return_title = #{returnTitle}, supplier_name = #{supplierName}, total_amount = #{totalAmount}, return_date = #{returnDate}, status = #{status}, return_reason = #{returnReason}, responsibility = #{responsibility}, attachment_urls = #{attachmentUrls}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
